commands.command:
$ErrorActionPreference = 'Stop'
$taskInput = 'D:\Temp\combat-library-behavior-j75bzt8f\runs\baseline-L07\request.txt'
$taskLog = & {
  Get-Content -LiteralPath $taskInput -Raw -Encoding UTF8
  '=== SHA256 ==='
  Get-FileHash -LiteralPath $taskInput -Algorithm SHA256 | Select-Object Path, Hash | ConvertTo-Json
} 2>&1
$taskExit = if ($?) { 0 } else { 1 }
$taskLog | Tee-Object -FilePath 'D:\Temp\combat-library-behavior-j75bzt8f\runs\baseline-L07\lookup-2.txt'
exit $taskExit

$ErrorActionPreference = 'Stop'
$taskRoot = 'D:\Temp\combat-library-behavior-j75bzt8f\baseline\skills\combat-director'
$taskLog = & {
  foreach ($taskRelative in @('references\library-workflow.md','references\technique-adaptation.md')) {
    $taskInput = Join-Path $taskRoot $taskRelative
    "=== $taskRelative (full read) ==="
    Get-Content -LiteralPath $taskInput -Raw -Encoding UTF8
    Get-FileHash -LiteralPath $taskInput -Algorithm SHA256 | Select-Object Path, Hash | ConvertTo-Json
  }
} 2>&1
$taskExit = if ($?) { 0 } else { 1 }
$taskLog | Tee-Object -FilePath 'D:\Temp\combat-library-behavior-j75bzt8f\runs\baseline-L07\lookup-3.txt'
exit $taskExit

$ErrorActionPreference = 'Stop'
$taskInput = 'D:\Temp\combat-library-behavior-j75bzt8f\baseline\skills\combat-director\library\techniques\arvin-tech-bagua.md'
$taskLog = & {
  $taskLine = 0
  Get-Content -LiteralPath $taskInput -Encoding UTF8 | ForEach-Object { $taskLine++; '{0}: {1}' -f $taskLine, $_ }
  '=== SHA256 ==='
  Get-FileHash -LiteralPath $taskInput -Algorithm SHA256 | Select-Object Path, Hash | ConvertTo-Json
} 2>&1
$taskExit = if ($?) { 0 } else { 1 }
$taskLog | Tee-Object -FilePath 'D:\Temp\combat-library-behavior-j75bzt8f\runs\baseline-L07\lookup-5.txt'
exit $taskExit

$ErrorActionPreference = 'Stop'
$taskOutput = 'D:\Temp\combat-library-behavior-j75bzt8f\runs\baseline-L07'
$taskLog = & {
  foreach ($taskName in @('answer.md','run.json')) {
    $taskFile = Get-Item -LiteralPath (Join-Path $taskOutput $taskName)
    if ($taskFile.Length -le 0) { throw "Empty output: $taskName" }
    $taskFile | Select-Object FullName, Length | ConvertTo-Json
  }
} 2>&1
$taskExit = if ($?) { 0 } else { 1 }
$taskLog | Tee-Object -FilePath (Join-Path $taskOutput 'lookup-6.txt')
exit $taskExit
